-- Add seven free sock IDs; preserve all existing save, privacy and entitlement rules.
CREATE OR REPLACE FUNCTION star_private.validate_builder_look()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v jsonb:=new.builder_look;
begin
 perform pg_advisory_xact_lock(hashtextextended('builder:'||new.player_id::text,0));
 if v is not null then
  if jsonb_typeof(v)<>'object' or (select count(*) from jsonb_object_keys(v))<>11 then raise exception 'Choose an available player look' using errcode='23514';end if;
  if jsonb_typeof(v->'skin') is distinct from 'string' or not((v->>'skin')=any(array['fair','light','medium','brown','deep'])) then raise exception 'Choose an available skin' using errcode='23514';end if;
  if jsonb_typeof(v->'hair') is distinct from 'string' or not((v->>'hair')=any(array['blonde','brown','black','ginger','silver'])) then raise exception 'Choose an available hair' using errcode='23514';end if;
  if jsonb_typeof(v->'hairstyle') is distinct from 'string' or not((v->>'hairstyle')=any(array['ponytail','curls','coils','braids'])) then raise exception 'Choose an available hairstyle' using errcode='23514';end if;
  if jsonb_typeof(v->'face') is distinct from 'string' or not((v->>'face')=any(array['oval','round','freckles'])) then raise exception 'Choose an available face' using errcode='23514';end if;
  if jsonb_typeof(v->'eyes') is distinct from 'string' or not((v->>'eyes')=any(array['brown','blue','green','grey'])) then raise exception 'Choose an available eyes' using errcode='23514';end if;
  if jsonb_typeof(v->'build') is distinct from 'string' or not((v->>'build')=any(array['slim','standard','strong'])) then raise exception 'Choose an available build' using errcode='23514';end if;
  if jsonb_typeof(v->'top') is distinct from 'string' or not((v->>'top')=any(array['base','star','arsenal','chelsea','navy-tee','white-tee','hoodie','gold-hoodie','nike-club-hoodie','adidas-firebird-top','adidas-originals-tee','ua-tech-halfzip','puma-essentials-hoodie','hollister-baby-tee','hollister-ivy-jumper','bershka-raglan-tee','hm-rib-cardigan','whitefox-offstage-tee','juicy-velour-hoodie','whitefox-shadow-hoodie','whitefox-glacier-hoodie','nike-pro-crop','ellesse-pink-sweatshirt','home-2627-arsenal','home-2627-aston-villa','home-2627-birmingham','home-2627-brighton','home-2627-charlton','home-2627-chelsea','home-2627-crystal-palace','home-2627-everton','home-2627-liverpool','home-2627-london-city','home-2627-manchester-city','home-2627-manchester-united','home-2627-tottenham','home-2627-west-ham','home-2627-bristol-city','home-2627-burnley','home-2627-durham','home-2627-ipswich','home-2627-leicester','home-2627-newcastle','home-2627-nottingham-forest','home-2627-sheffield-united','home-2627-southampton','home-2627-sunderland','home-2627-watford','home-2627-wolves'])) then raise exception 'Choose an available top' using errcode='23514';end if;
  if jsonb_typeof(v->'bottoms') is distinct from 'string' or not((v->>'bottoms')=any(array['base','shorts','arsenal','chelsea','leggings','trackies','nike-club-joggers','adidas-firebird-trousers','puma-cargo-shorts','hollister-andi-jeans','bershka-denim-skirt','juicy-velour-trousers','nike-pro-shorts','adidas-leggings','ellesse-pink-joggers','home-2627-arsenal','home-2627-aston-villa','home-2627-birmingham','home-2627-brighton','home-2627-charlton','home-2627-chelsea','home-2627-crystal-palace','home-2627-everton','home-2627-liverpool','home-2627-london-city','home-2627-manchester-city','home-2627-manchester-united','home-2627-tottenham','home-2627-west-ham','home-2627-bristol-city','home-2627-burnley','home-2627-durham','home-2627-ipswich','home-2627-leicester','home-2627-newcastle','home-2627-nottingham-forest','home-2627-sheffield-united','home-2627-southampton','home-2627-sunderland','home-2627-watford','home-2627-wolves'])) then raise exception 'Choose an available bottoms' using errcode='23514';end if;
  if jsonb_typeof(v->'socks') is distinct from 'string' or not((v->>'socks')=any(array['none','white','navy','black','red','nike-ankle-white','nike-ankle-black','nike-crew-white','nike-crew-black','adidas-ankle-black','gain-the-edge-crew','cherry-ribbon','home-2627-arsenal','home-2627-aston-villa','home-2627-birmingham','home-2627-brighton','home-2627-charlton','home-2627-chelsea','home-2627-crystal-palace','home-2627-everton','home-2627-liverpool','home-2627-london-city','home-2627-manchester-city','home-2627-manchester-united','home-2627-tottenham','home-2627-west-ham','home-2627-bristol-city','home-2627-burnley','home-2627-durham','home-2627-ipswich','home-2627-leicester','home-2627-newcastle','home-2627-nottingham-forest','home-2627-sheffield-united','home-2627-southampton','home-2627-sunderland','home-2627-watford','home-2627-wolves'])) then raise exception 'Choose an available socks' using errcode='23514';end if;
  if jsonb_typeof(v->'accessory') is distinct from 'string' or not((v->>'accessory')=any(array['none','glasses','headband','gold-headband'])) then raise exception 'Choose an available accessory' using errcode='23514';end if;
  if jsonb_typeof(v->'boots') is distinct from 'string' or not((v->>'boots')=any(array['none','starter','ida-rise','furon-pink','tekela-white','morelia-ruby','superfly-pink','absolute-2006','total90-2004','stadio-1990','etrusco-1990','tiempo','copa','mercurial','predator','future','ultra','phantom','f50'])) then raise exception 'Choose boots from your locker' using errcode='23514';end if;
  if v->>'boots' not in ('none','starter') and not exists(select 1 from public.player_cosmetic_unlocks u where u.player_id=new.player_id and u.cosmetic='boot-'||(v->>'boots')) then raise exception 'Unlock these boots first' using errcode='23514';end if;
  if (v->>'top'='gold-hoodie' or v->>'accessory'='gold-hoodie') and not exists(select 1 from public.player_cosmetic_unlocks u where u.player_id=new.player_id and u.cosmetic='avatar-captain') then raise exception 'Earn your first coach badge' using errcode='23514';end if;
  if (v->>'top'='gold-headband' or v->>'accessory'='gold-headband') and not exists(select 1 from public.player_cosmetic_unlocks u where u.player_id=new.player_id and u.cosmetic='decoration-laurel') then raise exception 'Earn three coach badges' using errcode='23514';end if;
 end if;
 if (new.builder_on_card or exists(select 1 from public.player_squads s where s.player_id=new.player_id and 'my-player'=any(s.footballers))) and (v is null or v->>'top'='base' or v->>'bottoms'='base') then raise exception 'Choose a top and bottoms while your player is on your card or in your squad' using errcode='23514';end if;
 return new;
end $function$;

revoke all on function star_private.validate_builder_look() from public,anon,authenticated;
notify pgrst,'reload schema';

